// TestTinkV3.cs —— KAT tests for the tink v3 frame skeleton (C#), zero deps.
// Vectors are generated by the tie reference implementation (tlib ext/tink.tie)
// and must match byte-for-byte (same vector set as the tink-c / tink-python /
// tink-rust / tink-java ports).
// Run: dotnet run

using System;
using System.Text;
using static Tink.TinkV3;

internal static class TestTinkV3
{
    private static int s_failures;

    private static void Check(bool cond, string name)
    {
        if (cond)
        {
            Console.WriteLine("[PASS] " + name);
        }
        else
        {
            s_failures++;
            Console.WriteLine("[FAIL] " + name);
        }
    }

    private static byte[] Pat(int n)
    {
        var b = new byte[n];
        for (int i = 0; i < n; i++)
        {
            b[i] = (byte)((i * 7 + 3) & 0xFF);
        }
        return b;
    }

    private static byte[] Seq(int n)
    {
        var b = new byte[n];
        for (int i = 0; i < n; i++)
        {
            b[i] = (byte)i;
        }
        return b;
    }

    private static string Hex(ReadOnlySpan<byte> b)
    {
        return Convert.ToHexString(b).ToLowerInvariant();
    }

    private static int Main()
    {
        // ---- CRC32C KAT ----
        Check(Crc32C(Encoding.UTF8.GetBytes("123456789")) == 0xE3069283u, "crc_123456789");
        Check(Crc32C(Pat(9)) == 2452382926u, "crc_pat9");
        Check(Crc32C(new byte[32]) == 2324772522u, "crc_rfc_zeros");
        var ff32 = new byte[32];
        Array.Fill(ff32, (byte)0xFF);
        Check(Crc32C(ff32) == 1655221059u, "crc_rfc_ff");
        Check(Crc32C(Seq(32)) == 1188919630u, "crc_rfc_inc");

        // ---- single frames ----
        var f13 = MsgEncode(Pat(13));
        Check(Hex(f13) == "746b0304000c0000000000000000000d030a11181f262d343b424950571d47ab1e",
            "single_frame_13");
        var f32 = MsgEncode(Seq(32));
        Check(Hex(f32) == ("746b0304000c00000000000000000020000102030405060708090a0b0c0d0e0f"
                + "101112131415161718191a1b1c1d1e1fee038132"),
            "single_frame_32inc");
        var fempty = MsgEncode(ReadOnlySpan<byte>.Empty);
        Check(Hex(fempty) == "746b0304000c00000000000000000000e7ccf215", "empty_frame");

        // ---- EXT frame ----
        var fext = FrameEncodeExt(Encoding.ASCII.GetBytes("x"), new byte[] { 0x00, 0x02, 0x00, 0x01, 0x05 });
        Check(Hex(fext) == "746b0304000d000000000000000000010005000200010578479e613c", "ext_frame_kat");
        var rext = MsgDecode(fext, 0);
        Check(rext is not null && rext.Payload.AsSpan().SequenceEqual(Encoding.ASCII.GetBytes("x"))
                && rext.Next == fext.Length,
            "ext_frame_decode");

        // ---- fragmented message (70000B -> two OFFSET fragments) ----
        var p70 = Pat(70000);
        var f70 = MsgEncode(p70);
        bool ok = f70.Length == 70048;
        ok = ok && Hex(f70.AsSpan(0, 16)) == "746b030400140000000000000000ffff";
        ok = ok && Hex(f70.AsSpan(65551, 4)) == "112dd201";
        ok = ok && Hex(f70.AsSpan(65555, 20)) == "746b0304001c000000000000000111790000fffb";
        ok = ok && Hex(f70.AsSpan(f70.Length - 4, 4)) == "38fb521f";
        Check(ok, "fragmented_layout");
        var r70 = MsgDecode(f70, 0);
        Check(r70 is not null && r70.Payload.AsSpan().SequenceEqual(p70) && r70.Next == f70.Length,
            "fragmented_roundtrip");
        var bad = (byte[])f70.Clone();
        bad[65600] ^= 0x01;
        Check(MsgDecode(bad, 0) is null, "fragmented_tamper_reject");

        // ---- boundaries ----
        var p65 = Pat(65535);
        var f65 = FrameEncode(p65);
        bool ok2 = f65.Length == 65555;
        ok2 = ok2 && Hex(f65.AsSpan(0, 16)) == "746b0304000c0000000000000000ffff";
        ok2 = ok2 && Hex(f65.AsSpan(f65.Length - 4, 4)) == "4995f11e";
        Check(ok2, "max_single_65535");
        Check(MsgEncode(p65.AsSpan(0, 65532)).Length == 65532 + 2 * 24, "boundary_65532_two_frags");
        // v1 frames are rejected (generational upgrade)
        byte[] v1 = { 0, 0, 0, 3, 0xAA, 0xBB, 0xCC, 0, 0, 0, 0 };
        Check(MsgDecode(v1, 0) is null, "v1_rejected");

        if (s_failures > 0)
        {
            Console.WriteLine(s_failures + " checks FAILED");
            return 1;
        }
        Console.WriteLine("all tests passed");
        return 0;
    }
}
